:root {
  --bg: #1e1b2e;
  --bg-accent: #2a2640;
  --card: #ffffff;
  --ink: #1e1b2e;
  --muted: #5b5670;
  --accent: #6c5ce7;
  --accent-strong: #4a3bd0;
  --focus: #ffd166;
  --radius: 16px;
  --shadow: 0 20px 45px rgba(10, 6, 30, 0.45);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--ink);
  background: radial-gradient(circle at 20% 0%, var(--bg-accent), var(--bg) 60%);
}

.card {
  width: 100%;
  max-width: 560px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 28px 24px 24px;
}

.card-header {
  text-align: center;
  margin-bottom: 20px;
}

h1 {
  margin: 0 0 6px;
  font-size: 1.6rem;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 0.95rem;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  margin-bottom: 24px;
}

.swatch {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.swatch-color {
  height: 96px;
  border-radius: 12px;
  border: 1px solid rgba(0, 0, 0, 0.12);
  transition: transform 0.15s ease;
}

.swatch-hex {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.8rem;
  text-align: center;
  color: var(--muted);
  letter-spacing: 0.02em;
  user-select: all;
}

.lock-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 100%;
  min-height: 34px;
  padding: 4px 6px;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  background: #f2f0f8;
  border: 1px solid #ddd9ec;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.lock-btn:hover {
  background: #e7e3f6;
  color: var(--ink);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: translateY(1px);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent-strong);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-strong);
  color: #fff;
}

.actions {
  display: flex;
  justify-content: center;
}

.btn-generate {
  width: 100%;
  min-height: 48px;
  padding: 12px 20px;
  font: inherit;
  font-size: 1.05rem;
  font-weight: 700;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

.btn-generate:hover {
  background: var(--accent-strong);
}

.btn-generate:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn-generate:active {
  transform: translateY(1px);
}

@media (max-width: 420px) {
  .palette {
    grid-template-columns: repeat(2, 1fr);
  }

  .swatch:last-child {
    grid-column: span 2;
  }

  .swatch:last-child .swatch-color {
    height: 72px;
  }
}

(function () {
  "use strict";

  var paletteEl = document.getElementById("palette");
  var generateBtn = document.getElementById("generate");

  var SWATCH_COUNT = 5;

  // ---------- Color helpers ----------
  function hslToRgb(h, s, l) {
    h = ((h % 360) + 360) % 360;
    s /= 100;
    l /= 100;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r = 0, g = 0, b = 0;

    if (h < 60) { r = c; g = x; }
    else if (h < 120) { r = x; g = c; }
    else if (h < 180) { g = c; b = x; }
    else if (h < 240) { g = x; b = c; }
    else if (h < 300) { r = x; b = c; }
    else { r = c; b = x; }

    return [
      Math.round((r + m) * 255),
      Math.round((g + m) * 255),
      Math.round((b + m) * 255)
    ];
  }

  function rgbToHex(rgb) {
    return "#" + rgb.map(function (v) {
      var hex = v.toString(16).toUpperCase();
      return hex.length === 1 ? "0" + hex : hex;
    }).join("");
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  // ---------- Harmony generation ----------
  // Pick a random harmony scheme and return 5 HSL colors.
  function generateHarmony() {
    var baseHue = randomInt(0, 359);
    var schemes = ["analogous", "complementary", "triadic", "split"];
    var scheme = schemes[randomInt(0, schemes.length - 1)];
    var hues = [];
    var i;

    if (scheme === "analogous") {
      for (i = -2; i <= 2; i++) {
        hues.push(baseHue + i * 24);
      }
    } else if (scheme === "complementary") {
      hues = [baseHue, baseHue + 12, baseHue + 180, baseHue + 192, baseHue + 168];
    } else if (scheme === "triadic") {
      hues = [baseHue, baseHue + 120, baseHue + 240, baseHue + 60, baseHue + 300];
    } else {
      hues = [baseHue, baseHue + 30, baseHue + 150, baseHue + 210, baseHue + 180];
    }

    var sat = randomInt(55, 85);
    var lightBase = randomInt(45, 62);

    return hues.map(function (h, index) {
      var l = Math.min(82, Math.max(28, lightBase + (index - 2) * 6));
      return { h: h, s: sat, l: l };
    });
  }

  function hslToHex(color) {
    return rgbToHex(hslToRgb(color.h, color.s, color.l));
  }

  // ---------- State ----------
  var state = [];

  function createInitialState() {
    var colors = generateHarmony();
    state = colors.map(function (c) {
      return { hex: hslToHex(c), locked: false };
    });
  }

  // ---------- Rendering ----------
  function render() {
    paletteEl.innerHTML = "";

    state.forEach(function (item, index) {
      var swatch = document.createElement("div");
      swatch.className = "swatch";

      var colorBox = document.createElement("div");
      colorBox.className = "swatch-color";
      colorBox.style.backgroundColor = item.hex;
      colorBox.setAttribute("aria-hidden", "true");

      var hexLabel = document.createElement("div");
      hexLabel.className = "swatch-hex";
      hexLabel.textContent = item.hex;

      var lockBtn = document.createElement("button");
      lockBtn.type = "button";
      lockBtn.className = "lock-btn";
      lockBtn.setAttribute("aria-pressed", item.locked ? "true" : "false");
      lockBtn.setAttribute("aria-label", "Lock color " + item.hex + " (swatch " + (index + 1) + ")");
      lockBtn.textContent = item.locked ? "Locked" : "Lock";

      lockBtn.addEventListener("click", function () {
        state[index].locked = !state[index].locked;
        render();
      });

      swatch.appendChild(colorBox);
      swatch.appendChild(hexLabel);
      swatch.appendChild(lockBtn);
      paletteEl.appendChild(swatch);
    });
  }

  // ---------- Generate ----------
  function generatePalette() {
    var fresh = generateHarmony();
    state = state.map(function (item, index) {
      if (item.locked) {
        return item;
      }
      return { hex: hslToHex(fresh[index]), locked: false };
    });
    render();
  }

  generateBtn.addEventListener("click", generatePalette);

  // ---------- Init ----------
  createInitialState();
  render();
})();
